     SELECT '81' DIVISION_ID, 'Ampere Electricity' END_CUSTOMER, 'A16RT4003' PROJECT_CODE, 'Ampere Electricity_FR_DOI' SCM_SITE_ID, 'EUR' CURRENCY, 'Mass' FCST_TYPE FROM DUAL
