     UNION ALL SELECT '81' DIVISION_ID, 'HKMC' END_CUSTOMER, 'A20MB1002' PROJECT_CODE, 'MOBIS_SK_GBY' SCM_SITE_ID, 'EUR' CURRENCY, 'Mass' FCST_TYPE FROM DUAL
