     UNION ALL SELECT '81' DIVISION_ID, 'HKMC' END_CUSTOMER, 'A21HC1017' PROJECT_CODE, 'HKMC_KR_HWS' SCM_SITE_ID, 'KRW' CURRENCY, 'Mass' FCST_TYPE FROM DUAL
