     UNION ALL SELECT '81' DIVISION_ID, 'HKMC' END_CUSTOMER, 'A22MZ1002' PROJECT_CODE, 'HKMC_WA_CZ_NVS' SCM_SITE_ID, 'EUR' CURRENCY, 'Mass' FCST_TYPE FROM DUAL
     UNION ALL SELECT '81' DIVISION_ID, 'HKMC' END_CUSTOMER, 'A22MZ1002' PROJECT_CODE, 'MOBIS_CZ_NVS' SCM_SITE_ID, 'EUR' CURRENCY, 'Mass' FCST_TYPE FROM DUAL
     UNION ALL SELECT '81' DIVISION_ID, 'KIA' END_CUSTOMER, 'A21HC1017' PROJECT_CODE, 'KIA_KR_GMG' SCM_SITE_ID, 'KRW' CURRENCY, 'Mass' FCST_TYPE FROM DUAL
     UNION ALL SELECT '81' DIVISION_ID, 'KIA' END_CUSTOMER, 'A21HC1017' PROJECT_CODE, 'KIA_SK_TEP' SCM_SITE_ID, 'EUR' CURRENCY, 'Mass' FCST_TYPE FROM DUAL
     UNION ALL SELECT '81' DIVISION_ID, 'Man Truck & Bus' END_CUSTOMER, 'A17MA4001' PROJECT_CODE, 'Man Truck & Bus_PL_STE' SCM_SITE_ID, 'USD' CURRENCY, 'Mass' FCST_TYPE FROM DUAL
     UNION ALL SELECT '81' DIVISION_ID, 'PSA' END_CUSTOMER, 'A15PA7001' PROJECT_CODE, 'PSA_FR_MHS' SCM_SITE_ID, 'EUR' CURRENCY, 'Mass' FCST_TYPE FROM DUAL
     UNION ALL SELECT '81' DIVISION_ID, 'PSA' END_CUSTOMER, 'A15PA7004' PROJECT_CODE, 'PSA_FR_MHS' SCM_SITE_ID, 'EUR' CURRENCY, 'Mass' FCST_TYPE FROM DUAL
     UNION ALL SELECT '81' DIVISION_ID, 'PSA' END_CUSTOMER, 'A15PA7004' PROJECT_CODE, 'PSA_FR_RNS' SCM_SITE_ID, 'EUR' CURRENCY, 'Mass' FCST_TYPE FROM DUAL
     UNION ALL SELECT '81' DIVISION_ID, 'PSA' END_CUSTOMER, 'A17PA9001' PROJECT_CODE, 'PSA_FR_MHS' SCM_SITE_ID, 'EUR' CURRENCY, 'Mass' FCST_TYPE FROM DUAL
     UNION ALL SELECT '81' DIVISION_ID, 'PSA' END_CUSTOMER, 'A21PA2001' PROJECT_CODE, 'PSA AS_FR_VEL' SCM_SITE_ID, 'EUR' CURRENCY, 'Mass' FCST_TYPE FROM DUAL
     UNION ALL SELECT '81' DIVISION_ID, 'PSA' END_CUSTOMER, 'A21PA2003' PROJECT_CODE, 'PSA AS_FR_VEL' SCM_SITE_ID, 'EUR' CURRENCY, 'Mass' FCST_TYPE FROM DUAL
     UNION ALL SELECT '81' DIVISION_ID, 'PSA' END_CUSTOMER, 'A21PA2004' PROJECT_CODE, 'PSA AS_FR_VEL' SCM_SITE_ID, 'EUR' CURRENCY, 'Mass' FCST_TYPE FROM DUAL
     UNION ALL SELECT '81' DIVISION_ID, 'PSA' END_CUSTOMER, 'A22PA2001' PROJECT_CODE, 'PSA_FR_JKI' SCM_SITE_ID, 'EUR' CURRENCY, 'Mass' FCST_TYPE FROM DUAL
     UNION ALL SELECT '81' DIVISION_ID, 'PSA' END_CUSTOMER, 'A22PA2001' PROJECT_CODE, 'PSA_PL_GWC' SCM_SITE_ID, 'EUR' CURRENCY, 'Mass' FCST_TYPE FROM DUAL
     UNION ALL SELECT '81' DIVISION_ID, 'Porsche' END_CUSTOMER, 'A15PE4001' PROJECT_CODE, 'Porsche_DE_SHM' SCM_SITE_ID, 'USD' CURRENCY, 'Mass' FCST_TYPE FROM DUAL
     UNION ALL SELECT '81' DIVISION_ID, 'Porsche' END_CUSTOMER, 'A21PE1001' PROJECT_CODE, 'Porsche_SK_DNV' SCM_SITE_ID, 'USD' CURRENCY, 'Mass' FCST_TYPE FROM DUAL
     UNION ALL SELECT '81' DIVISION_ID, 'Porsche AS' END_CUSTOMER, 'A22PE4002' PROJECT_CODE, 'Porsche AS_DE_SSN' SCM_SITE_ID, 'USD' CURRENCY, 'Mass' FCST_TYPE FROM DUAL
     UNION ALL SELECT '81' DIVISION_ID, 'Renault' END_CUSTOMER, 'A16RT4003-I01' PROJECT_CODE, 'Renault_FR_CLE' SCM_SITE_ID, 'EUR' CURRENCY, 'Mass' FCST_TYPE FROM DUAL
     UNION ALL SELECT '81' DIVISION_ID, 'Renault' END_CUSTOMER, 'A22RT4003' PROJECT_CODE, 'Renault_FR_HRB' SCM_SITE_ID, 'EUR' CURRENCY, 'Mass' FCST_TYPE FROM DUAL
     UNION ALL SELECT '81' DIVISION_ID, 'Renault' END_CUSTOMER, 'A22RT4007' PROJECT_CODE, 'Renault AS_FR_FNS' SCM_SITE_ID, 'EUR' CURRENCY, 'Mass' FCST_TYPE FROM DUAL
     UNION ALL SELECT '81' DIVISION_ID, 'VAL' END_CUSTOMER, 'A22VT1001' PROJECT_CODE, 'VAL_DE_222' SCM_SITE_ID, 'USD' CURRENCY, 'Mass' FCST_TYPE FROM DUAL
     UNION ALL SELECT '81' DIVISION_ID, 'VW' END_CUSTOMER, 'A15AI7001' PROJECT_CODE, 'VW_DE_KAS' SCM_SITE_ID, 'USD' CURRENCY, 'Mass' FCST_TYPE FROM DUAL
     UNION ALL SELECT '81' DIVISION_ID, 'VW' END_CUSTOMER, 'A17VA4001' PROJECT_CODE, 'VW_CZ_MBV' SCM_SITE_ID, 'USD' CURRENCY, 'Mass' FCST_TYPE FROM DUAL
     UNION ALL SELECT '81' DIVISION_ID, 'VW' END_CUSTOMER, 'A17VA4001' PROJECT_CODE, 'VW_DE_BWE' SCM_SITE_ID, 'USD' CURRENCY, 'Mass' FCST_TYPE FROM DUAL
     UNION ALL SELECT '81' DIVISION_ID, 'VW' END_CUSTOMER, 'A21VA4003' PROJECT_CODE, 'VW AS_DE_KAS' SCM_SITE_ID, 'USD' CURRENCY, 'Mass' FCST_TYPE FROM DUAL
     UNION ALL SELECT '81' DIVISION_ID, 'VW' END_CUSTOMER, 'A21VA4004' PROJECT_CODE, 'VW AS_DE_KAS' SCM_SITE_ID, 'USD' CURRENCY, 'Mass' FCST_TYPE FROM DUAL
     UNION ALL SELECT '81' DIVISION_ID, 'Volvo' END_CUSTOMER, 'A17VO4001' PROJECT_CODE, 'Volvo_BE_GNE' SCM_SITE_ID, 'USD' CURRENCY, 'Mass' FCST_TYPE FROM DUAL),
VER AS (SELECT A.DIVISION_ID, A.VERSION_NO,
               TO_CHAR(FN_NEXT_DAY(TO_DATE(A.YYYYMMDD,'YYYYMMDD'),'MON') - 7, 'YYYYMMDD') RESULT_TO,
               TO_CHAR(FN_NEXT_DAY(TO_DATE(A.YYYYMMDD,'YYYYMMDD'),'MON') - 7 + 52*7 - 1, 'YYYYMMDD') PLAN_TO
          FROM (SELECT DIVISION_ID, MAX(VERSION_NO) VERSION_NO, MAX(YYYYMMDD) YYYYMMDD FROM DM_MST_VERSION
                 WHERE VERSION_TYPE = 'SP_W' AND NVL(ATTRIBUTE7,'N') = 'Y' AND DIVISION_ID = '81' GROUP BY DIVISION_ID) A),
SPI AS (SELECT DISTINCT PC.DIVISION_ID, PC.PROJECT_CODE, PC.SCM_SITE_ID, PC.ITEM_ID, PC.FCST_TYPE, PC.CURRENCY
          FROM DM_PLN_SALES_PLAN_C PC JOIN VER ON VER.DIVISION_ID = PC.DIVISION_ID AND VER.VERSION_NO = PC.VERSION_NO
         WHERE PC.QTY <> 0 AND PC.MEASURE = 'RTF_SYS_RP' AND PC.YYYYMMDD BETWEEN VER.RESULT_TO AND VER.PLAN_TO),
LUP AS (SELECT SEGMENT1, SEGMENT2 FROM SCM_ADM_LOOKUP_MASTER_DETAIL
         WHERE LOOKUP_TYPE = 'SALES_TYPE_CODE' AND VALID_YN = 'Y' AND SEGMENT4 <> 'FREE'),
PV AS (SELECT DISTINCT DIVISION_ID, ITEM_ID FROM DM_MST_ITEM_SINGLE_V WHERE ITEM_TYPE = 'P' AND ACTIVE_FLAG = 'Y'),
D AS (
SELECT T.*,
       (SELECT COUNT(*) FROM SCM_MST_SITE_ITEM I WHERE I.DIVISION_ID = T.DIVISION_ID AND I.PROJECT_CODE = T.PROJECT_CODE
           AND I.SCM_SITE_ID = T.SCM_SITE_ID AND I.VALID_YN = 'Y') S3_MASTER,
       (SELECT COUNT(*) FROM LUP WHERE LUP.SEGMENT2 = T.FCST_TYPE) S4_FCST,
       (SELECT COUNT(*) FROM SCM_MST_SITE_ITEM I JOIN PV ON PV.DIVISION_ID = I.DIVISION_ID AND PV.ITEM_ID = I.ITEM_ID
         WHERE I.DIVISION_ID = T.DIVISION_ID AND I.PROJECT_CODE = T.PROJECT_CODE AND I.SCM_SITE_ID = T.SCM_SITE_ID AND I.VALID_YN = 'Y') S5_PRODUCT,
       (SELECT COUNT(DISTINCT I.ITEM_ID) FROM SCM_MST_SITE_ITEM I JOIN PV ON PV.DIVISION_ID = I.DIVISION_ID AND PV.ITEM_ID = I.ITEM_ID
          JOIN SPI ON SPI.DIVISION_ID = I.DIVISION_ID AND SPI.PROJECT_CODE = I.PROJECT_CODE AND SPI.SCM_SITE_ID = I.SCM_SITE_ID AND SPI.ITEM_ID = I.ITEM_ID
         WHERE I.DIVISION_ID = T.DIVISION_ID AND I.PROJECT_CODE = T.PROJECT_CODE AND I.SCM_SITE_ID = T.SCM_SITE_ID AND I.VALID_YN = 'Y') S6_SALESPLAN,
       (SELECT COUNT(DISTINCT I.ITEM_ID) FROM SCM_MST_SITE_ITEM I JOIN PV ON PV.DIVISION_ID = I.DIVISION_ID AND PV.ITEM_ID = I.ITEM_ID
          JOIN SPI ON SPI.DIVISION_ID = I.DIVISION_ID AND SPI.PROJECT_CODE = I.PROJECT_CODE AND SPI.SCM_SITE_ID = I.SCM_SITE_ID AND SPI.ITEM_ID = I.ITEM_ID
          JOIN LUP ON LUP.SEGMENT1 = SPI.FCST_TYPE AND LUP.SEGMENT2 = T.FCST_TYPE
         WHERE I.DIVISION_ID = T.DIVISION_ID AND I.PROJECT_CODE = T.PROJECT_CODE AND I.SCM_SITE_ID = T.SCM_SITE_ID AND I.VALID_YN = 'Y'
           AND SPI.CURRENCY = T.CURRENCY) S7_EXPANDED
  FROM TMP T)
-- [A] 조합별 확장 결과와 탈락 단계 (EXPANDED_MODELS × 3개월 = 해당 조합의 저장 행 단위)
SELECT PROJECT_CODE, SCM_SITE_ID, CURRENCY, FCST_TYPE, S3_MASTER, S4_FCST, S5_PRODUCT, S6_SALESPLAN, S7_EXPANDED EXPANDED_MODELS,
       CASE WHEN S3_MASTER = 0 THEN '③ 마스터(SITE_ITEM) 유효 모델 없음'
            WHEN S4_FCST = 0 THEN '④ FCST type 코드 없음'
            WHEN S5_PRODUCT = 0 THEN '⑤ 제품(P)·활성 모델 없음'
            WHEN S6_SALESPLAN = 0 THEN '⑥ 최신 Sales Plan(MRF=Y) RTF 수량 없음'
            WHEN S7_EXPANDED = 0 THEN '⑦ Sales Plan 은 있으나 통화/FCST 불일치'
            ELSE 'OK' END REASON
  FROM D
 ORDER BY CASE WHEN S7_EXPANDED = 0 THEN 0 ELSE 1 END, PROJECT_CODE, SCM_SITE_ID;

-- [B] 요약은 [A] 결과에서 REASON 별 건수 / EXPANDED_MODELS 합계(× 3개월) 로 확인
